import assert from 'node:assert/strict';import {Soccer} from '../rules.js';
let g=new Soccer();g.freeze=0;Object.assign(g.ball,{x:0,z:-20.4,vz:-10,y:1});g.update(.02);assert.equal(g.score[0],1);assert(g.freeze>0);g.update(.1);assert.equal(g.score[0],1,'Goal counted once');g.freeze=0;Object.assign(g.ball,{x:9,z:-19,vz:-20,y:1});g.update(.03);assert(g.ball.vz>0,'End wall rebounds outside goal mouth');g.freeze=0;g.update(.016,new Set(['KeyW','ShiftLeft']),new Set(['Space']));assert(g.cars[0].y>0);assert(g.cars[0].boost<100);g.score=[4,0];g.freeze=0;Object.assign(g.ball,{x:0,z:-20.4,vz:-10,y:1});g.update(.02);assert(g.over);assert.equal(g.winner,0);
g=new Soccer();for(let i=0;i<12000&&!g.over;i++)g.update(1/60,new Set(['KeyW','KeyA','ShiftLeft']));assert(g.cars.every(c=>Number.isFinite(c.x)&&Math.abs(c.x)<=13.5));assert(Number.isFinite(g.ball.y));console.log('Boost Circuit: goal aperture, single score, walls, jump, boost, match win and long physics simulation passed.');
